const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').substring(0, 2000);
const source = body.source || 'chat_widget';
const url = body.url || '';

if (!message.trim()) {
  throw new Error('Empty message');
}

return [{ json: { message, source, url } }];

const response = $input.first().json;
const chatData = $('Extract Chat Message').first().json;

// Guess the customer's language from THEIR message, so a parse failure
// does not force the wrong-language fallback (EN question must not get an HR reply).
function guessLang(msg) {
  const s = (msg || '').toLowerCase();
  if (/[čćžšđ]/.test(s)) return 'HR';
  if (/\b(mogu|koliko|kosta|košta|dostava|placanje|plaćanje|proizvod|vas|vaš|hvala|molim|kako|zasto|zašto|je li|imate|narudzba|narudžba)\b/.test(s)) return 'HR';
  return 'EN';
}
const msgLang = guessLang(chatData && chatData.message);

// Mistral (OpenAI-compatible): text is at choices[0].message.content.
// n8n v4 HTTP node may also wrap the API body under .body — handle both.
const payload = (response && response.choices) ? response : (response && response.body && response.body.choices) ? response.body : response;
const text = payload && Array.isArray(payload.choices) && payload.choices[0] && payload.choices[0].message && payload.choices[0].message.content
  ? payload.choices[0].message.content
  : null;

let classification;
if (text) {
  try {
    // Strip accidental code fences if the model added any.
    const clean = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    classification = JSON.parse(clean);
  } catch (e) {
    classification = {
      category: 'FAQ', priority: 'P2', language: msgLang,
      summary: ('Unparseable model output: ' + String(text)).substring(0, 200),
      requires_human: true, suggested_action: 'Manual review needed', auto_reply: ''
    };
  }
} else {
  const err = payload && payload.error ? JSON.stringify(payload.error) : JSON.stringify(payload).substring(0, 300);
  classification = {
    category: 'FAQ', priority: 'P2', language: msgLang,
    summary: ('Mistral call failed: ' + err).substring(0, 200),
    requires_human: true, suggested_action: 'Check Mistral node', auto_reply: ''
  };
}

// If the model omitted language, fall back to the guessed one.
if (!classification.language) classification.language = msgLang;

if (classification.summary) {
  classification.summary = classification.summary.substring(0, 200).replace(/[<>]/g, '');
}

return [{ json: { ...chatData, ...classification } }];

const d = $input.first().json;
const autoReply = d.auto_reply || '';

const fallback = d.language === 'HR'
  ? 'Hvala na vašoj poruci! Naš tim će vam odgovoriti uskoro. Za hitne upite: support@metabelly.com'
  : 'Thank you for your message! Our team will get back to you shortly. For urgent enquiries: support@metabelly.com';

return [{ json: {
  auto_reply: autoReply || fallback,
  requires_human: d.requires_human,
  category: d.category,
  priority: d.priority,
  language: d.language
} }];
